//! Compares the UFF atom typing / 1-2 rest lengths of
//! `distgeom::uff_params` against RDKit reference data generated by
//! `tools/gen_uff_typing_reference.py`.

use molecule_optimizer_rs::distgeom::uff_params::{
    calc_bond_rest_length, uff_atom_labels, uff_atom_params, uff_params_by_label,
};
use molecule_optimizer_rs::io;
use serde_json::Value;

const DATA: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/data/etkdg/");

/// Molecules whose UFF typing differs from RDKit because of a perception
/// difference upstream of the typer (not in `uff_params`).  The test fails if
/// this set changes in either direction, so fixing the cause forces an update.
/// (Currently empty: caffeine's exocyclic C=O typing was fixed by the RDKit
/// aromatic valence rules in `Molecule::explicit_valence`.)
const KNOWN_PERCEPTION_DIFFS: &[&str] = &[];

fn check(sdf: &str, json: &str) -> (usize, usize) {
    let text = std::fs::read_to_string(format!("{DATA}{sdf}")).unwrap();
    let mols = io::read_sdf(&text).unwrap();
    let refs: Value = serde_json::from_str(&std::fs::read_to_string(format!("{DATA}{json}")).unwrap()).unwrap();
    let refs = refs.as_array().unwrap();
    assert_eq!(mols.len(), refs.len());

    let mut failures = Vec::new();
    let mut failed_names = Vec::new();
    let mut nbonds = 0;
    for (m, r) in mols.iter().zip(refs) {
        let name = r["name"].as_str().unwrap();
        let labels = uff_atom_labels(m);
        let (params, found_all) = uff_atom_params(m);
        let mut errs = Vec::new();
        if found_all != r["has_all"].as_bool().unwrap() {
            errs.push(format!("found_all {found_all} vs {}", r["has_all"]));
        }
        for (i, rl) in r["labels"].as_array().unwrap().iter().enumerate() {
            if let Some(rl) = rl.as_str()
                && labels[i] != rl
            {
                errs.push(format!("atom {i} label {} vs {rl}", labels[i]));
            }
        }
        for (i, t) in r["theta0"].as_array().unwrap().iter().enumerate() {
            if let Some(t) = t.as_f64() {
                match params[i] {
                    Some(p) if (p.theta0.to_degrees() - t).abs() < 1e-9 => {}
                    _ => errs.push(format!("atom {i} theta0 ({}) vs {t}", labels[i])),
                }
            }
        }
        for b in r["bonds"].as_array().unwrap() {
            let i = b[0].as_u64().unwrap() as usize;
            let j = b[1].as_u64().unwrap() as usize;
            let Some(bi) = m.bond_between(i, j) else {
                errs.push(format!("bond {i}-{j} missing"));
                continue;
            };
            let bo = m.bond(bi).order.as_f64();
            let ours = match (params[i], params[j]) {
                (Some(a), Some(c)) if bo > 0.0 => Some(calc_bond_rest_length(bo, &a, &c)),
                _ => None,
            };
            nbonds += 1;
            match (ours, b[2].as_f64()) {
                (Some(x), Some(y)) if (x - y).abs() < 1e-9 => {}
                (None, None) => {}
                (x, y) => errs.push(format!("bond {i}-{j} r0 {x:?} vs {y:?} ({} {})", labels[i], labels[j])),
            }
        }
        if !errs.is_empty() {
            failures.push(format!("{name}: {}", errs.join("; ")));
            failed_names.push(name);
        }
    }
    for f in &failures {
        println!("{f}");
    }
    let expected: Vec<&str> =
        KNOWN_PERCEPTION_DIFFS.iter().copied().filter(|k| refs.iter().any(|r| r["name"] == *k)).collect();
    assert_eq!(failed_names, expected, "{} of {} molecules differ", failures.len(), mols.len());
    (mols.len(), nbonds)
}

#[test]
fn uff_typing_matches_rdkit() {
    let (n, nb) = check("molecules.sdf", "uff_typing.json");
    assert_eq!(n, 79);
    println!("{n} molecules, {nb} bonds compared");
}

#[test]
fn uff_typing_extra_matches_rdkit() {
    let (n, nb) = check("uff_typing_extra.sdf", "uff_typing_extra.json");
    println!("{n} molecules, {nb} bonds compared");
}

#[test]
fn params_lookup() {
    assert!(uff_params_by_label("S_3+6").is_some());
    assert!(uff_params_by_label("Se2+2").is_none());
}
